    int32_t idx = 0;
    size_t i = 0, j = 0;
    uint8_t byte4[4], byte3[3];

    while ( dataSize-- && ( pDataToDecode[idx] != '=' ) && IsBase64( pDataToDecode[idx] ) )
    {
        byte4[i++] = pDataToDecode[idx]; idx++;
        if ( i == 4 )
        {
            for ( i = 0; i < 4; i++ )
            {
